import{z as n,x as B,o as s,c as d,q as l,j as i,D as t,d as e,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"多级反馈队列","description":"","frontmatter":{"title":"多级反馈队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mlfq.md","filePath":"cs/mlfq.md","lastUpdated":1791413859000}'),m={name:"cs/mlfq.md"};function p(D,a,C,_,u,F){const r=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=l('<h1 id="多级反馈队列" tabindex="-1">多级反馈队列 <a class="header-anchor" href="#多级反馈队列" aria-label="Permalink to &quot;多级反馈队列&quot;">​</a></h1><div class="epigraph"><p>多级反馈用任务自己的近期行为当估计：用完量子就降档、更大片；经常阻塞就留在高档、短片——不必事先知道作业长度。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Corbato 兼容时间共享系统的反馈调度整理</footer></div><p><a href="/cs/rr-quantum">上一课</a>的单队列 RR 对所有人同一 \\(q\\)，也做不到 SJF 那种「短者先」——因为不知道谁短。缺口是 <strong>MLFQ</strong>：若干 RR 队列，优先级从高到低，量子从短到长；任务用完本档量子则降入下一档，阻塞或等待过久可再升。本课钉这套反馈，不当成某内核源码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SJF 要预言；RR 不预言也不偏向短作业（除了 I/O 型用不完片）。MLFQ 把「刚才用尽量子」当成「可能是 CPU 型」的证据，把它放到更长量子、更低优先级的队列，让高档留给像交互那样短跑就睡的人。缺口不是再调一个全局 \\(q\\)，而是<strong>多条 runqueue 加迁移规则</strong>。</p><p><span class="marginnote">饥饿：CPU 型降到最低档后，若高档一直有交互，低档可能长期摸不到 CPU。对策是定期提升，或保证低档仍有 CPU 份额。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>队列 \\(Q_0,Q_1,\\ldots\\)：\\(Q_0\\) 先被选，其内 RR。用尽 \\(q_i\\) 降到 \\(Q_{i+1}\\)，\\(q_{i+1}\\gt q_i\\)。阻塞离开时记住档位，唤醒回原档或升档（实现各异）。调度：总是跑当前非空的最高档。本课不把具体 \\(q_i\\) 表当标准。</p><p><span class="marginnote">数字实例：设 \\(q_0=2\\) ms、\\(q_1=4\\) ms、\\(q_2=8\\) ms。一个要连续跑 10 ms 的 CPU 型任务会被切成 \\(2+4+4\\) 三段——第一次用完 2 ms 降到 \\(Q_1\\)，第二次用完 4 ms 降到 \\(Q_2\\)，之后都在 8 ms 的低档里轮转；而每次只跑 1 ms 就去等键盘的交互任务永远待在 \\(Q_0\\)。</span></p>',9)),(s(),i(A,null,{default:t(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q0%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%20%E7%9F%AD%E9%87%8F%E5%AD%90%22%5D%20--%3E%20DOWN%5B%22%E7%94%A8%E5%B0%BD%E5%88%99%E9%99%8D%E6%A1%A3%22%5D%0A%20%20Q1%5B%22%E8%BE%83%E4%BD%8E%20%E8%BE%83%E9%95%BF%E9%87%8F%E5%AD%90%22%5D%20--%3E%20DOWN2%5B%22%E5%86%8D%E9%99%8D%22%5D%0A%20%20QN%5B%22%E6%9C%80%E4%BD%8E%E6%A1%A3%20%E9%95%BF%E9%87%8F%E5%AD%90%22%5D%20--%3E%20BOOST%5B%22%E5%AE%9A%E6%9C%9F%E6%8F%90%E5%8D%87%E9%98%B2%E9%A5%A5%E9%A5%BF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("与"),E("a",{href:"/cs/cpu-vs-io-bound"},"CPU 型与 I/O 型"),e("对齐：反馈就是在线分类。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"MLFQ 用行为近似 SJF 且保持 RR 的响应：新任务或交互待在高档。规则必须防博弈：用户若每 \\(q-ε\\) 主动让出以假装 I/O 型，会占住高档——教材承认启发式可被骗。内核若用睡眠时间而不是「是否自愿 yield」来升档，骗术弱一些。本课不写攻防细节。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易把降档理解成「惩罚」。实际上降档只是一次估计更新——系统在重新回答「你现在更像 CPU 型还是 I/O 型」，定期提升会把估计推倒重来，所以低档不是牢房，只是「暂定你是长跑型」。")],-1)),(s(),i(A,null,{default:t(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E4%BB%BB%E5%8A%A1%E5%9C%A8%20Qi%20%E4%B8%8A%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20USED%7B%22%E7%94%A8%E5%B0%BD%E6%9C%AC%E6%A1%A3%E9%87%8F%E5%AD%90%3F%22%7D%0A%20%20USED%20--%3E%7C%22%E6%98%AF%20%E7%96%91%E4%BC%BCCPU%E5%9E%8B%22%7C%20DEMO%5B%22%E9%99%8D%E5%85%A5%20Qi%2B1%20%E6%9B%B4%E9%95%BF%E9%87%8F%E5%AD%90%22%5D%0A%20%20USED%20--%3E%7C%22%E5%90%A6%20%E6%8F%90%E5%89%8D%E9%98%BB%E5%A1%9E%22%7C%20WAIT%5B%22%E7%9D%A1%E7%9C%A0%2F%E7%AD%89I%2FO%22%5D%0A%20%20WAIT%20--%3E%20WAKE%5B%22%E5%94%A4%E9%86%92%22%5D%0A%20%20WAKE%20--%3E%20KEEP%5B%22%E5%9B%9E%E5%8E%9F%E6%A1%A3%E6%88%96%E5%8D%87%E6%A1%A3%20%E7%96%91%E4%BC%BC%E4%BA%A4%E4%BA%92%22%5D%0A%20%20DEMO%20--%3E%20AGE%5B%22%E5%AE%9A%E6%9C%9F%E6%8F%90%E5%8D%87%E5%85%A8%E5%91%98%E5%9B%9E%E9%AB%98%E6%A1%A3%22%5D%0A%20%20KEEP%20--%3E%20AGE%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 Linux CFS：CFS 用虚拟时间而不是固定多档量子。也不把 Solaris 旧 MLFQ 参数当定律。优先级反转还没锁：下一课才把「高优先级等低优先级持锁」请进来。</p><p>后课默认：分时可以用反馈分档。一旦有锁，静态或反馈的优先级都会反转，下一课讲优先级反转。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLFQ：多档 RR，用尽降档，近似短作业优先且不需预言。</li><li>须防低档饥饿与用户博弈。</li><li>锁引起的优先级反转是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Corbato et al. 时间共享系统。</li></ul>',5))])}const q=n(m,[["render",p]]);export{h as __pageData,q as default};
